<!-- CyberManju OS — Persistent, app-local Home workspaces. Not Android Recents. -->
<!-- Role: app-local Home UI only. Integrates: Vue and bounded persisted workspace state. -->
<template>
  <section ref="root" class="home-studio" :class="`identity-${state.theme}`" aria-label="Personal home workspaces" @touchstart.stop.passive="touchStart" @touchmove.stop="touchMove" @touchend.stop="touchEnd" @touchcancel.stop="resetTouch">
    <div class="studio-heading">
      <div><span class="studio-kicker">YOUR ORBIT / {{ String(activeIndex + 1).padStart(2, '0') }}</span><h2>{{ activePage.title }}</h2></div>
      <div class="studio-tools"><button type="button" :aria-pressed="overview" aria-label="Eagle view of home workspaces" @click="overview = !overview"><AppIcon name="solar:widget-bold" :size="20" /></button><button ref="addButton" class="studio-add" type="button" aria-label="Add apps or widgets to home" @click="openPicker('apps')"><span aria-hidden="true">+</span></button></div>
    </div>
    <p class="studio-status" role="status">{{ message || `${state.pages.length} / ${MAX_WORKSPACES} screens · saved on this device` }}</p>
    <template v-if="overview">
      <div class="overview-bar"><strong>Eagle view</strong><button type="button" aria-label="Zoom out overview" @click="zoom = Math.max(.65, zoom - .15)">−</button><span>{{ Math.round(zoom * 100) }}%</span><button type="button" aria-label="Zoom in overview" @click="zoom = Math.min(1.4, zoom + .15)">+</button><button type="button" @click="zoom = 1; panX = 0; panY = 0">Reset</button><button type="button" @click="overview = false">Done</button></div>
      <p class="studio-hint">Home screens only, not Android Recents. Tap a screen; drag your tiles between screens. Two fingers pan / pinch here.</p>
      <div class="eagle-viewport">
        <div class="eagle-canvas" :style="{ transform: `translate(${panX}px, ${panY}px) scale(${zoom})` }">
          <article v-for="(page, index) in state.pages" :key="page.id" class="eagle-card" :class="{ current: page.id === state.activeId, 'drop-ready': dragging && page.id !== dragging.from }" :data-workspace-id="page.id">
            <button class="eagle-select" type="button" :aria-label="`Go to ${page.title}`" @click="navigate(index); overview = false"><span>{{ String(index + 1).padStart(2, '0') }}</span><strong>{{ page.title }}</strong><small>{{ page.items.length }} items</small></button>
            <div class="eagle-items"><button v-for="item in page.items.slice(0, 4)" :key="item.id" class="eagle-chip" type="button" :aria-label="`Move ${itemTitle(item)}; use Edit on home for keyboard move controls`" @pointerdown="beginDrag($event, item, page.id)" @pointerup="finishDrag" @pointercancel="dragging = null"><AppIcon :name="itemIcon(item)" :size="16" /><span>{{ itemTitle(item) }}</span></button></div><button v-if="page.items.length > 4" class="eagle-more" type="button" @click="navigate(index); overview = false">+ {{ page.items.length - 4 }} more tiles</button>
            <span v-if="!page.items.length" class="eagle-empty">Room for something new +</span>
          </article>
        </div>
      </div>
    </template>
    <template v-else>
      <div class="screen-tools"><button type="button" :aria-pressed="editing" @click="editing = !editing">{{ editing ? 'Done editing' : 'Edit screen' }}</button><button type="button" @click="openPicker('widgets')">Widget library</button></div>
      <label v-if="editing" class="screen-name">Screen name<input v-model="activePage.title" maxlength="40" aria-label="Screen name" /></label>
      <Transition name="orbit" mode="out-in">
        <div :key="activePage.id" class="workspace-content">
          <div v-if="!activePage.items.length" class="empty-orbit"><div class="pixel-city" aria-hidden="true"><i /><i /><i /><i /><i /></div><h3>A new corner of your world</h3><p>Apps, small rituals, a little pixel magic.<br />Make this screen yours.</p><button type="button" @click="openPicker('apps')">+ Add your first item</button></div>
          <div class="workspace-apps" v-if="activeApps.length"><article v-for="item in activeApps" :key="item.id" class="workspace-app"><button class="workspace-launch" type="button" :aria-label="`Open ${itemTitle(item)}`" @click="launch(item.ref)" @contextmenu.prevent="customize(item.ref)"><span class="workspace-app-icon"><img v-if="appFor(item.ref)?.image" :src="appFor(item.ref)?.image" alt="" /><AppIcon v-else :name="itemIcon(item)" :size="25" /></span><span>{{ itemTitle(item) }}</span></button><div v-if="editing" class="item-edit"><button type="button" :aria-label="`Customize ${itemTitle(item)}`" @click="customize(item.ref)">Style</button><button type="button" :aria-label="`Remove ${itemTitle(item)} from screen`" @click="removeItem(item)">×</button><label :aria-label="`Move ${itemTitle(item)} to screen`"><select :value="activePage.id" :aria-label="`Move ${itemTitle(item)} to screen`" @change="moveItem(item, ($event.target as HTMLSelectElement).value)"><option v-for="p in state.pages" :key="p.id" :value="p.id">{{ p.title }}</option></select></label></div></article></div>
          <div class="workspace-widgets"><article v-for="item in activeWidgets" :key="item.id" class="workspace-widget"><header><span><AppIcon :name="itemIcon(item)" :size="16" />{{ itemTitle(item) }}</span><button v-if="editing" type="button" :aria-label="`Remove ${itemTitle(item)}`" @click="removeItem(item)">×</button></header><HomeLocalWidget :item="item" :app-id="widgetFor(item.ref)?.appId" @update="item.data = $event" @open="launch" /><label v-if="editing" class="widget-move">Move to<select :value="activePage.id" :aria-label="`Move ${itemTitle(item)} to screen`" @change="moveItem(item, ($event.target as HTMLSelectElement).value)"><option v-for="p in state.pages" :key="p.id" :value="p.id">{{ p.title }}</option></select></label></article></div>
          <p v-if="editing" class="studio-hint">Remove only unpins the tile; it never uninstalls an app. Move tiles using the screen selector or Eagle view.</p>
        </div>
      </Transition>
      <nav class="screen-nav" aria-label="Home screen navigation"><button type="button" :disabled="activeIndex === 0" aria-label="Previous home screen" @click="navigate(activeIndex - 1)">←</button><span>{{ activeIndex + 1 }} / {{ state.pages.length }}</span><button type="button" :disabled="activeIndex === state.pages.length - 1" aria-label="Next home screen" @click="navigate(activeIndex + 1)">→</button></nav>
      <p class="studio-hint gesture-hint">Swipe sideways between screens · Three fingers up for Eagle view</p>
    </template>
    <div v-if="picker" class="studio-veil" @click.self="closePicker" @keydown="dialogKeys">
      <section ref="dialog" class="studio-picker" role="dialog" aria-modal="true" aria-labelledby="home-picker-title" tabindex="-1">
        <header class="picker-title"><div><span class="studio-kicker">PERSONALIZE YOUR ORBIT</span><h2 id="home-picker-title">Make room for you</h2></div><button type="button" aria-label="Close add to home" @click="closePicker">×</button></header>
        <div class="picker-tabs" role="group" aria-label="Personalization categories"><button v-for="tab in (['apps', 'widgets', 'identity'] as const)" :key="tab" type="button" :aria-pressed="picker === tab" @click="picker = tab">{{ tab === 'apps' ? 'Apps' : tab === 'widgets' ? 'Widgets' : 'Identity' }}</button></div>
        <template v-if="picker !== 'identity'"><label class="picker-search"><AppIcon name="solar:magnifier-bold" :size="18" /><input v-model="pickerQuery" type="search" :placeholder="picker === 'apps' ? 'Find an app to pin…' : 'Find your next widget…'" aria-label="Search add to home library" /></label><p class="studio-hint">Adding to {{ activePage.title }} · {{ activePage.items.length }} / {{ MAX_ITEMS_PER_WORKSPACE }} items</p></template>
        <div v-if="picker === 'apps'" class="picker-list"><button v-for="app in pickerApps" :key="app.id" type="button" :disabled="hasItem('app', app.id)" @click="add('app', app.id)"><AppIcon :name="app.icon" :size="23" /><span><strong>{{ app.label }}</strong><small>{{ app.id.startsWith('android:') ? 'Android app shortcut' : 'CyberManju app' }}</small></span><span>{{ hasItem('app', app.id) ? 'Added' : '+' }}</span></button><p v-if="!pickerApps.length">No matching apps.</p><p v-if="androidApps.status.value === 'error'" role="status">Android apps could not be loaded. Open All apps to retry.</p></div>
        <template v-else-if="picker === 'widgets'"><div class="widget-filters" role="group" aria-label="Widget integration types"><button v-for="type in (['All types', 'CyberManju', 'Android widgets', 'Service concepts'] as const)" :key="type" type="button" :aria-pressed="widgetType === type" @click="widgetType = type">{{ type }}</button></div><div class="widget-filters"><button v-for="category in categories" :key="category" type="button" :aria-pressed="widgetCategory === category" @click="widgetCategory = category">{{ category }}</button></div><p class="studio-hint">Local tools work now. App cards open apps; native widgets and service concepts need separate integrations and explicit permission.</p><div class="picker-list widget-library"><article v-for="widget in pickerWidgets" :key="widget.id"><AppIcon :name="widget.icon" :size="23" /><span><strong>{{ widget.title }}</strong><small>{{ widget.description }}</small><em>{{ widget.kind === 'local' ? 'On-device · ready' : widget.kind === 'app-link' ? 'App shortcut · ready' : widget.kind === 'native' ? 'Android host required' : 'Concept · not connected' }}</em><a v-if="widget.sourceUrl" :href="widget.sourceUrl" target="_blank" rel="noopener noreferrer">Inspiration ↗</a></span><button type="button" :aria-label="`Add ${widget.title} widget`" :disabled="!widgetReady(widget) || hasItem('widget', widget.id)" @click="add('widget', widget.id)">{{ hasItem('widget', widget.id) ? 'Added' : widgetReady(widget) ? '+' : 'Later' }}</button></article><p v-if="!pickerWidgets.length">No matching widgets.</p></div></template>
        <div v-else class="identity-list"><button v-for="identity in identities" :key="identity.id" type="button" :class="`preview-${identity.id}`" :aria-pressed="state.theme === identity.id" @click="state.theme = identity.id"><span class="identity-swatch" aria-hidden="true" /><strong>{{ identity.title }}</strong><small>{{ identity.description }}</small></button><p class="studio-hint">Original palettes and pixel artwork. No flashing effects; reduced-motion preferences are respected.</p></div>
        <p class="picker-feedback" role="status">{{ message }}</p>
      </section>
    </div>
  </section>
</template>
<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import AppIcon from '@/components/AppIcon.vue'
import HomeLocalWidget from '@/components/HomeLocalWidget.vue'
import { useAndroidApps } from '@/composables/useAndroidApps'
import { homeWidgetCatalog } from '@/data/homeWidgetCatalog'
import { HOME_WORKSPACE_KEY, MAX_ITEMS_PER_WORKSPACE, MAX_WORKSPACES, normalizeHomeState, addHomeItem, moveHomeItem, removeHomeItem, classifyHomeGesture, type HomeItem } from '@/utils/homeWorkspaces'
type HomeApp = { id: string; label: string; icon: string; image?: string }
const props = defineProps<{ apps: HomeApp[]; initialIds: string[] }>()
const emit = defineEmits<{ open: [id: string]; customize: [id: string] }>()
const androidApps = useAndroidApps()
const message = ref('')
function load() { try { return JSON.parse(localStorage.getItem(HOME_WORKSPACE_KEY) || 'null') } catch { return null } }
const state = ref(normalizeHomeState(load(), props.initialIds))
const overview = ref(false), editing = ref(false), zoom = ref(1), panX = ref(0), panY = ref(0)
const root = ref<HTMLElement>(), dialog = ref<HTMLElement>(), addButton = ref<HTMLButtonElement>()
const activeIndex = computed(() => Math.max(0, state.value.pages.findIndex(p => p.id === state.value.activeId)))
const activePage = computed(() => state.value.pages[activeIndex.value]!)
const activeApps = computed(() => activePage.value.items.filter(i => i.kind === 'app'))
const activeWidgets = computed(() => activePage.value.items.filter(i => i.kind === 'widget'))
const allApps = computed<HomeApp[]>(() => [...props.apps, ...androidApps.apps.value.map(a => ({ id: `android:${a.packageName}`, label: a.label, icon: 'solar:widget-bold' }))])
function appFor(id: string) { return allApps.value.find(a => a.id === id) }
function widgetFor(id: string) { return homeWidgetCatalog.find(w => w.id === id) }
function itemTitle(item: HomeItem) { return item.kind === 'app' ? appFor(item.ref)?.label || 'Unavailable app' : widgetFor(item.ref)?.title || 'Unavailable widget' }
function itemIcon(item: HomeItem) { return (item.kind === 'app' ? appFor(item.ref)?.icon : widgetFor(item.ref)?.icon) || 'solar:widget-bold' }
watch(state, value => { try { localStorage.setItem(HOME_WORKSPACE_KEY, JSON.stringify(value)) } catch { message.value = 'Storage unavailable — changes last only for this session.' } }, { deep: true, immediate: true })
function navigate(index: number) { if (state.value.pages[index]) { state.value.activeId = state.value.pages[index]!.id; message.value = '' } }
async function launch(id: string) { if (id.startsWith('android:')) { try { await androidApps.openApp(id.slice(8)) } catch { message.value = 'This Android app is unavailable. Try refreshing All apps.' } } else emit('open', id) }
function customize(id: string) { if (!id.startsWith('android:')) emit('customize', id); else message.value = 'Customize Android apps in All apps.' }
function hasItem(kind: HomeItem['kind'], id: string) { return activePage.value.items.some(i => i.kind === kind && i.ref === id) }
function add(kind: HomeItem['kind'], id: string) { const item = { id: globalThis.crypto?.randomUUID?.() || `item-${Date.now()}-${Math.random().toString(36).slice(2)}`, kind, ref: id }; if (hasItem(kind, id)) return; message.value = addHomeItem(state.value, activePage.value.id, item) ? 'Added to this screen.' : `This screen is full (${MAX_ITEMS_PER_WORKSPACE} items). Choose another screen.` }
function removeItem(item: HomeItem) { removeHomeItem(state.value, activePage.value.id, item.id); message.value = 'Removed from this screen.' }
function moveItem(item: HomeItem, target: string) { message.value = moveHomeItem(state.value, item.id, activePage.value.id, target) ? 'Moved to screen.' : 'Could not move: destination is full or already contains this item.' }
const picker = ref<'apps' | 'widgets' | 'identity' | null>(null), pickerQuery = ref(''), widgetCategory = ref('All'), widgetType = ref('All types')
let previousFocus: HTMLElement | null = null
async function openPicker(tab: 'apps' | 'widgets' | 'identity') { previousFocus = document.activeElement as HTMLElement; picker.value = tab; pickerQuery.value = ''; message.value = ''; if (androidApps.supported) void androidApps.refresh().catch(() => {}); await nextTick(); dialog.value?.focus() }
function closePicker() { picker.value = null; previousFocus?.focus() }
function dialogKeys(event: KeyboardEvent) { if (event.key === 'Escape') { event.stopPropagation(); closePicker(); return } if (event.key !== 'Tab') return; const nodes = Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea,a[href]') || []); const first = nodes[0], last = nodes[nodes.length - 1]; if (!first || !last) return; if (event.shiftKey && (document.activeElement === first || document.activeElement === dialog.value)) { event.preventDefault(); last.focus() } else if (!event.shiftKey && (document.activeElement === last || document.activeElement === dialog.value)) { event.preventDefault(); first.focus() } }
const pickerApps = computed(() => allApps.value.filter(a => a.label.toLowerCase().includes(pickerQuery.value.toLowerCase())))
const categories = computed(() => ['All', ...new Set(homeWidgetCatalog.map(w => w.category))])
const pickerWidgets = computed(() => homeWidgetCatalog.filter(w => (widgetType.value === 'All types' || widgetType.value === 'CyberManju' && ['local', 'app-link'].includes(w.kind) || widgetType.value === 'Android widgets' && w.kind === 'native' || widgetType.value === 'Service concepts' && w.kind === 'concept') && (widgetCategory.value === 'All' || w.category === widgetCategory.value) && `${w.title} ${w.description}`.toLowerCase().includes(pickerQuery.value.toLowerCase())))
function widgetReady(widget: typeof homeWidgetCatalog[number]) { return ['clock', 'notes', 'counter', 'pixel-pet', 'focus', 'checklist'].includes(widget.id) && widget.kind === 'local' || widget.kind === 'app-link' && !!widget.appId && props.apps.some(a => a.id === widget.appId) }
const identities = [{ id: 'aurora' as const, title: 'Neon orbit', description: 'Cyan signals, violet skies. A calm cyberpunk cockpit.' }, { id: 'pixel' as const, title: 'Pixel district', description: 'Mint terminals and warm pink. Tiny worlds, real rituals.' }, { id: 'mono' as const, title: 'Quiet signal', description: 'Low distraction, sharp contrast. Space to think.' }]
const dragging = ref<{ id: string; from: string; x: number; y: number } | null>(null)
function beginDrag(event: PointerEvent, item: HomeItem, from: string) { if (event.button !== 0 || !overview.value) return; event.stopPropagation(); dragging.value = { id: item.id, from, x: event.clientX, y: event.clientY }; (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId) }
function finishDrag(event: PointerEvent) { if (!dragging.value) return; const drag = dragging.value; dragging.value = null; if (Math.hypot(event.clientX - drag.x, event.clientY - drag.y) < 12) return; const target = document.elementFromPoint(event.clientX, event.clientY)?.closest<HTMLElement>('[data-workspace-id]')?.dataset.workspaceId; if (target && target !== drag.from) message.value = moveHomeItem(state.value, drag.id, drag.from, target) ? 'Tile moved.' : 'Destination is full or already contains this item.' }
let gesture: { x: number; y: number; fingers: number; lastX: number; lastY: number; distance: number; zoom: number; panX: number; panY: number } | null = null
function center(touches: TouchList) { const points = Array.from(touches); return { x: points.reduce((a, p) => a + p.clientX, 0) / points.length, y: points.reduce((a, p) => a + p.clientY, 0) / points.length } }
function distance(touches: TouchList) { return touches.length >= 2 ? Math.hypot(touches[0]!.clientX - touches[1]!.clientX, touches[0]!.clientY - touches[1]!.clientY) : 0 }
function touchStart(event: TouchEvent) { if (picker.value || dragging.value || event.touches.length === 2 && !(event.target as HTMLElement).closest('.eagle-viewport')) { gesture = null; return } const point = center(event.touches); if (point.x < 24 || point.x > innerWidth - 24 || point.y > innerHeight - 32) return; if (event.touches.length === 1 && ((event.target as HTMLElement).closest('button,input,textarea,select,a') || overview.value)) { gesture = null; return } gesture = { ...point, fingers: event.touches.length, lastX: point.x, lastY: point.y, distance: distance(event.touches), zoom: zoom.value, panX: panX.value, panY: panY.value } }
function touchMove(event: TouchEvent) { if (!gesture || picker.value) return; if (event.touches.length === gesture.fingers) { const point = center(event.touches); gesture.lastX = point.x; gesture.lastY = point.y } if (event.touches.length === 2 && gesture.fingers === 2 && overview.value) { event.preventDefault(); const point = center(event.touches); zoom.value = Math.max(.65, Math.min(1.4, gesture.zoom * distance(event.touches) / Math.max(1, gesture.distance))); panX.value = Math.max(-600, Math.min(600, gesture.panX + point.x - gesture.x)); panY.value = Math.max(-600, Math.min(600, gesture.panY + point.y - gesture.y)) } else if (gesture.fingers >= 3) event.preventDefault() }
function touchEnd(event: TouchEvent) { if (!gesture || event.touches.length) return; const end = event.changedTouches[0]; if (!end) { resetTouch(); return } const action = classifyHomeGesture(gesture.lastX - gesture.x, gesture.lastY - gesture.y, gesture.fingers); if (action === 'overview-open') overview.value = true; if (action === 'overview-close') overview.value = false; if (!overview.value && action === 'next') navigate(activeIndex.value + 1); if (!overview.value && action === 'previous') navigate(activeIndex.value - 1); resetTouch() }
function resetTouch() { gesture = null; dragging.value = null }
onMounted(() => { if (androidApps.supported) void androidApps.refresh().catch(() => {}) })
function removeApp(id: string) { for (const page of state.value.pages) { const item = page.items.find(i => i.kind === 'app' && i.ref === id); if (item) removeHomeItem(state.value, page.id, item.id) } }
function reorderApp(id: string, direction: -1 | 1) { const items = activePage.value.items; const from = items.findIndex(i => i.kind === 'app' && i.ref === id); const target = from + direction; if (from < 0 || target < 0 || target >= items.length) return; const [item] = items.splice(from, 1); items.splice(target, 0, item!) }
defineExpose({ removeApp, reorderApp })
onUnmounted(resetTouch)
</script>
